import math

def closest(p,line):
    best=None; bd=1e9
    for a,b in zip(line,line[1:]):
        dx=b[0]-a[0]; dy=b[1]-a[1]
        t=max(0,min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/max(1e-9,dx*dx+dy*dy)))
        q=(a[0]+t*dx,a[1]+t*dy)
        d=(p[0]-q[0])**2+(p[1]-q[1])**2
        if d<bd: best=q; bd=d
    return best

def control(obs):
    m=obs['local_map']; left=m['left_rail']; right=m['right_rail']
    mids=[]
    for line,other in ((left,right),(right,left)):
        for p in line:
            q=closest(p,other)
            if q is not None:
                mids.append(((p[0]+q[0])/2,(p[1]+q[1])/2))
    candidates=[p for p in mids if p[0]>2]
    if not candidates: return (0,0,180)
    x,y=min(candidates,key=lambda p:abs(math.hypot(p[0]+1.9,p[1])-12))
    x+=1.9
    curvature=2*y/max(16,x*x+y*y)
    desired=math.degrees(math.asin(max(-0.72,min(0.72,10.2*curvature))))
    h=obs['hitch_deg']
    feed=math.degrees(math.atan(3.9*math.sin(math.radians(h))/(10.2+0.35*math.cos(math.radians(h)))))
    steer=max(-42,min(42,feed+1.65*(h-desired)))
    speed=1.2 if abs(desired)<15 else 0.8
    if abs(h-desired)>18: speed=0.55
    if abs(h)>55:
        wake('High articulation; stopped for review')
        return (steer,0,180)
    return (steer,-speed,180)

